import{_ as e,c as i,o as l,ag as o}from"./chunks/framework.DJBJE7_Z.js";const b=JSON.parse('{"title":"Android 端更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"overview/changelog/android.md","filePath":"overview/changelog/android.md"}'),d={name:"overview/changelog/android.md"};function r(t,a,c,n,h,u){return l(),i("div",null,a[0]||(a[0]=[o('<h1 id="android-端更新日志" tabindex="-1">Android 端更新日志 <a class="header-anchor" href="#android-端更新日志" aria-label="Permalink to &quot;Android 端更新日志&quot;">​</a></h1><h2 id="_1-3-0-2026-06-09" tabindex="-1">[1.3.0] - 2026-06-09 <a class="header-anchor" href="#_1-3-0-2026-06-09" aria-label="Permalink to &quot;[1.3.0] - 2026-06-09&quot;">​</a></h2><ul><li>更新内嵌 ForgeJS 至 1.3.0。 <ul><li>同步 1.3.0 正式版页面管理能力，稳定支持 <code>addPage</code>、<code>gotoPage</code>、<code>deletePage</code>、<code>pageList</code>、<code>currentPageId</code>。</li><li><code>WhiteboardApplication.insertImage</code> 支持 Web 兼容的 <code>pageId</code>、<code>fit</code>、<code>role</code> options。</li><li>IndexedNavigation bridge handler 对齐 Web 命名，提升跨端一致性。</li></ul></li><li>增加 Forge Room 回调日志，便于排查房间事件与状态流转问题。</li></ul><h2 id="_1-3-0-beta-1-2026-05-20" tabindex="-1">[1.3.0-beta.1] - 2026-05-20 <a class="header-anchor" href="#_1-3-0-beta-1-2026-05-20" aria-label="Permalink to &quot;[1.3.0-beta.1] - 2026-05-20&quot;">​</a></h2><ul><li>同步 Web 1.3.0 白板 pageId API 命名，新增 <code>addPage</code>、<code>gotoPage</code>、<code>deletePage</code>、<code>pageList</code>、<code>currentPageId</code>。</li><li><code>WhiteboardApplication.insertImage</code> 支持 Web 兼容的 <code>pageId</code>、<code>fit</code>、<code>role</code> options，并保留 <code>insertImage(src, pageId)</code> 兼容调用。</li><li>IndexedNavigation bridge handler 切换到 <code>whiteboard.indexed*</code> 命名，Native <code>IndexedNavigation</code> 公共接口保持不变。</li><li>Demo 增加页面管理入口与 <code>addPage + insertImage + gotoPage + delete</code> 组合测试。</li><li>增加 WhiteboardApplication 与 IndexedNavigation 页面语义基础集成测试。</li></ul><h2 id="_1-2-1-2026-05-27" tabindex="-1">[1.2.1] - 2026-05-27 <a class="header-anchor" href="#_1-2-1-2026-05-27" aria-label="Permalink to &quot;[1.2.1] - 2026-05-27&quot;">​</a></h2><ul><li>更新 内嵌 ForgeJS 至 1.2.1。 <ul><li>修复加入房间时偶现的数据重复或错乱问题，提升多人同步稳定性。</li><li>修复绘制曲线过程中清空页面可能导致异常或笔迹残留的问题。</li><li>增强页面导航容错能力，避免异常页面数据导致白板不可用。</li></ul></li></ul><h2 id="_1-2-0-2026-05-11" tabindex="-1">[1.2.0] - 2026-05-11 <a class="header-anchor" href="#_1-2-0-2026-05-11" aria-label="Permalink to &quot;[1.2.0] - 2026-05-11&quot;">​</a></h2><ul><li>更新 内嵌 ForgeJS 至 1.2.0。 <ul><li>同步 Whiteboard 相关修复，移除曲线压感点带来的异常影响。</li><li>同步 Whiteboard 文本点初始化优化，提升绘制稳定性。</li></ul></li><li>新增 <code>WhiteboardApplication.insertImage</code> 方法，支持在白板上插入图片。</li></ul><h2 id="_1-1-3-2026-04-16" tabindex="-1">[1.1.3] - 2026-04-16 <a class="header-anchor" href="#_1-1-3-2026-04-16" aria-label="Permalink to &quot;[1.1.3] - 2026-04-16&quot;">​</a></h2><ul><li>更新 内嵌 ForgeJS 至 1.1.4。</li><li>修复 房间加入完成前注册消息监听导致的时序问题。</li></ul><h2 id="_1-1-2-2026-04-01" tabindex="-1">[1.1.2] - 2026-04-01 <a class="header-anchor" href="#_1-1-2-2026-04-01" aria-label="Permalink to &quot;[1.1.2] - 2026-04-01&quot;">​</a></h2><ul><li>修复关键状态变更后快照未及时上传，导致后续恢复状态不完整的问题。</li><li>修复服务端快照不存在时加入房间可能恢复失败的问题。</li></ul><h2 id="_1-1-1-2026-01-28" tabindex="-1">[1.1.1] - 2026-01-28 <a class="header-anchor" href="#_1-1-1-2026-01-28" aria-label="Permalink to &quot;[1.1.1] - 2026-01-28&quot;">​</a></h2><ul><li>新增 <code>WhiteboardApplication.setPerformanceMode</code> 动态设置性能模式。</li></ul><h2 id="_1-1-0-2025-12-24" tabindex="-1">[1.1.0] - 2025-12-24 <a class="header-anchor" href="#_1-1-0-2025-12-24" aria-label="Permalink to &quot;[1.1.0] - 2025-12-24&quot;">​</a></h2><ul><li>修复 白板绘制时偶现画笔涂层错位问题</li></ul><h2 id="_1-1-0-beta03-2025-12-10" tabindex="-1">[1.1.0-beta03] - 2025-12-10 <a class="header-anchor" href="#_1-1-0-beta03-2025-12-10" aria-label="Permalink to &quot;[1.1.0-beta03] - 2025-12-10&quot;">​</a></h2><ul><li>修复 SlideApp 缩略图显示异常问题</li><li>新增 <code>RoomErrorCode.ROOM_SNAPSHOT_RESTORE_FAILED</code> 错误处理</li><li>新增 <code>RoomOptions.timeout</code> 配置项，支持自定义房间连接超时时间</li></ul><h2 id="_1-1-0-beta02-2025-12-05" tabindex="-1">[1.1.0-beta02] - 2025-12-05 <a class="header-anchor" href="#_1-1-0-beta02-2025-12-05" aria-label="Permalink to &quot;[1.1.0-beta02] - 2025-12-05&quot;">​</a></h2><ul><li>新增 只读可写（Writable）能力</li><li>优化 只读模式的冲突处理逻辑，提升整体稳定性</li><li>优化 窗口管理（层级、缩放、最大化等）</li><li>修复 多项边界问题并提升测试覆盖率</li><li>新增 Demo 中的权限与可写模式示例</li></ul><h2 id="_1-0-4-2025-11-27" tabindex="-1">[1.0.4] - 2025-11-27 <a class="header-anchor" href="#_1-0-4-2025-11-27" aria-label="Permalink to &quot;[1.0.4] - 2025-11-27&quot;">​</a></h2><ul><li>修复偶现数据错乱问题</li></ul><h2 id="_1-0-3-2025-09-10" tabindex="-1">[1.0.3] - 2025-09-10 <a class="header-anchor" href="#_1-0-3-2025-09-10" aria-label="Permalink to &quot;[1.0.3] - 2025-09-10&quot;">​</a></h2><ul><li>修复冲突处理逻辑异常，避免出现错误的数据交换</li><li>修复多窗口场景偶现不同步</li></ul><h2 id="_1-0-2-2025-08-10" tabindex="-1">[1.0.2] - 2025-08-10 <a class="header-anchor" href="#_1-0-2-2025-08-10" aria-label="Permalink to &quot;[1.0.2] - 2025-08-10&quot;">​</a></h2><ul><li>修复多窗口下退出时的错误</li><li>修复加入房间时偶现的数据不一致问题</li></ul><h2 id="_1-0-1-2025-08-19" tabindex="-1">[1.0.1] - 2025-08-19 <a class="header-anchor" href="#_1-0-1-2025-08-19" aria-label="Permalink to &quot;[1.0.1] - 2025-08-19&quot;">​</a></h2><ul><li>修复 兼容低版本 Android WebView（ES5）</li><li>修复 历史记录记录错误</li><li>新增 更多日志信息</li></ul><h2 id="_1-0-0-2025-07-24" tabindex="-1">[1.0.0] - 2025-07-24 <a class="header-anchor" href="#_1-0-0-2025-07-24" aria-label="Permalink to &quot;[1.0.0] - 2025-07-24&quot;">​</a></h2><ul><li>修复 离线用户信息导致的白板应用无法绘制</li><li>支持 16 KB 的页面大小</li></ul><h2 id="_1-0-0-alpha01-2025-07-16" tabindex="-1">[1.0.0-alpha01] - 2025-07-16 <a class="header-anchor" href="#_1-0-0-alpha01-2025-07-16" aria-label="Permalink to &quot;[1.0.0-alpha01] - 2025-07-16&quot;">​</a></h2><ul><li>新增 <code>WindowManager</code> 支持</li><li>新增 <code>SlideApplication</code> 支持, 用于幻灯片应用。</li><li>新增 <code>ImageryDocApplication</code> 支持, 用于图像文档应用。</li><li><strong>BREAKING CHANGE</strong>: 与 0.1.x 内部数据不兼容，需要强制升级。</li></ul><h2 id="_0-1-13-2025-06-12" tabindex="-1">[0.1.13] - 2025-06-12 <a class="header-anchor" href="#_0-1-13-2025-06-12" aria-label="Permalink to &quot;[0.1.13] - 2025-06-12&quot;">​</a></h2><ul><li>修复退出前清理白板应用不生效问题。</li></ul><h2 id="_0-1-12-2025-06-04" tabindex="-1">[0.1.12] - 2025-06-04 <a class="header-anchor" href="#_0-1-12-2025-06-04" aria-label="Permalink to &quot;[0.1.12] - 2025-06-04&quot;">​</a></h2><ul><li>新增 <code>WhiteboardApplication.updateViewport</code> 方法，布局变更时候更新白板视图区域。</li><li>新增 <code>Application.performPrivateFunction</code> 方法，允许调用部分私有方法。</li><li>支持设置主画布可见性。 例如 whiteboardApp.performPrivateFunction(&quot;setMainCanvasVisible:&quot;, false)</li><li>支持设置画面隐藏的延迟时间（单位：毫秒）。例如 whiteboardApp.performPrivateFunction(&quot;setDelayTranslateOut:&quot;, 1500)</li></ul><h2 id="_0-1-11-2025-05-21" tabindex="-1">[0.1.11] - 2025-05-21 <a class="header-anchor" href="#_0-1-11-2025-05-21" aria-label="Permalink to &quot;[0.1.11] - 2025-05-21&quot;">​</a></h2><ul><li>新增 <code>Room.setAppExtraOptionsProvider</code> 方法，用于设置应用额外参数。</li><li>修复 退出房间时部分数据未正确同步的问题。</li></ul><h2 id="_0-1-9-2025-04-17" tabindex="-1">[0.1.9] - 2025-04-17 <a class="header-anchor" href="#_0-1-9-2025-04-17" aria-label="Permalink to &quot;[0.1.9] - 2025-04-17&quot;">​</a></h2><ul><li>新增 <code>WhiteboardApplication.setWhiteboardTransparent</code>, 实现设置白板透明。</li></ul><h2 id="_0-1-8-2025-04-11" tabindex="-1">[0.1.8] - 2025-04-11 <a class="header-anchor" href="#_0-1-8-2025-04-11" aria-label="Permalink to &quot;[0.1.8] - 2025-04-11&quot;">​</a></h2><ul><li>更新 <code>DSBridge-Android</code> 至 3.0.5。</li></ul><h2 id="_0-1-7-2025-03-25" tabindex="-1">[0.1.7] - 2025-03-25 <a class="header-anchor" href="#_0-1-7-2025-03-25" aria-label="Permalink to &quot;[0.1.7] - 2025-03-25&quot;">​</a></h2><ul><li>修复 <code>RtmSocketProvider</code> 处理消息时的空指针异常。</li></ul><h2 id="_0-1-5-2025-03-19" tabindex="-1">[0.1.5] - 2025-03-19 <a class="header-anchor" href="#_0-1-5-2025-03-19" aria-label="Permalink to &quot;[0.1.5] - 2025-03-19&quot;">​</a></h2><ul><li>新增 <code>RoomRegion</code>, 支持 <code>RoomRegion.PRIVATE</code> 用于私有云部署。</li></ul><h2 id="_0-1-4-2025-03-14" tabindex="-1">[0.1.4] - 2025-03-14 <a class="header-anchor" href="#_0-1-4-2025-03-14" aria-label="Permalink to &quot;[0.1.4] - 2025-03-14&quot;">​</a></h2><ul><li>支持 Android 7.0 及以上版本。</li></ul><h2 id="_0-1-1-2024-12-06" tabindex="-1">[0.1.1] - 2024-12-06 <a class="header-anchor" href="#_0-1-1-2024-12-06" aria-label="Permalink to &quot;[0.1.1] - 2024-12-06&quot;">​</a></h2><ul><li>新增 <code>WhiteboardOptions.maxScaleRatio</code>，实现白板最大缩放比例配置，所有客户端配置必须一致，参数大于等于 1 或为 -1（表示无限制）。</li><li>新增 <code>WhiteboardApplication.translateCamera</code>，实现画布平移功能。</li><li>新增 <code>WhiteboardApplication.scaleCamera</code>，实现画布缩放功能，以画布中心为固定点。</li><li>新增 <code>WhiteboardApplication.resetCamera</code>，实现画布重置功能，缩放比例重置为 1，平移量重置为 [0, 0]。</li><li>新增 <code>WhiteboardApplication.enableCameraTranslate</code>，实现控制是否允许通过触摸手势控制相机的缩放和拖动，默认值为 <code>true</code>。</li><li>新增 <code>WhiteboardApplication.enableCameraBoundaryHighlight</code> ，实现控制是否允许在相机超出边界时显示警示高亮阴影，默认值为 <code>true</code>。</li><li>新增 <code>WhiteboardApplication.setCameraBoundaryColor</code>，实现设置相机超出边界时警示阴影的颜色。</li></ul><h2 id="_0-1-0-2024-11-27" tabindex="-1">[0.1.0] - 2024-11-27 <a class="header-anchor" href="#_0-1-0-2024-11-27" aria-label="Permalink to &quot;[0.1.0] - 2024-11-27&quot;">​</a></h2><ul><li>First stable release</li></ul><h2 id="_0-1-0-alpha01-2024-08-25" tabindex="-1">[0.1.0-alpha01] - 2024-08-25 <a class="header-anchor" href="#_0-1-0-alpha01-2024-08-25" aria-label="Permalink to &quot;[0.1.0-alpha01] - 2024-08-25&quot;">​</a></h2><ul><li>Initial release</li></ul>',55)]))}const _=e(d,[["render",r]]);export{b as __pageData,_ as default};
